import json, pathlib, collections
B = pathlib.Path('data/outputs-caching/batch-1')
def run(config, position_stamp, n=2):
    return next(B.joinpath(config).rglob(f'run-{position_stamp}-{n}'))
runs = {'A': run('A', '20261022T202856Z'), 'B': run('B', '20261022T210120Z'), 'C': run('C', '20261022T210843Z')}
for c, r in runs.items():
    doc = json.loads((r / 'plans.json').read_text())
    for phase in ('model', 'summaries'):
        reads = [(x['mark'], x['partitions']) for e in doc['executions'] if e['phase'] == phase and not e['description'].startswith('cache fill') for x in e['shuffle_reads']]
        exch = [x['partitions'] for e in doc['executions'] if e['phase'] == phase and not e['description'].startswith('cache fill') for x in e['exchanges'] if x['partitioning'] == 'hashpartitioning']
        print(c, phase, 'exchanges written', exch, 'marked reads', reads)
"

